styl:
u + .body .gmail-blend-screen { background: #000;
  mix-blend-mode: screen; }
u + .body .gmail-blend-diff { background: #000;
  mix-blend-mode: difference; }
.bgr-image { background: url("https://fsms.quadcode.com/storage/public/d6/29/f0vvhhgea139ulj0/bcg-333-1.png") center no-repeat;
  background-size: cover;
  background-color: #000; }
.brad-full { border-radius: 32px !important; }
.data { display: inline-block;
  padding: 6px 16px;
  background: #3f1907;
  border-radius: 12px;
  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 16px;
  line-height: 20px;
  color: #ff8516;
  text-align: left; }
@media screen and (max-width: 600px) {
  .data { font-size: 14px !important; }
}
.white-title { font-family: Helvetica !important;
  font-weight: 700;
  font-size: 40px;
  line-height: 50px;
  color: #fff;
  word-break: break-word; }
@media screen and (max-width: 600px) {
  .white-title { font-size: 26px !important;
    line-height: 32px !important; }
}
.white-text { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 400;
  font-size: 18px;
  line-height: 27px;
  color: #fff;
  padding-right: 20px; }
@media screen and (max-width: 600px) {
  .white-text { padding-right: 0 !important; }
}
.pb16 { padding-bottom: 16px; }
.pt16 { padding-top: 16px; }
